(()=>{const examples={pod:{field:'pod UID',entities:['pod-a','pod-b'],note:'Two UID values → two pod entities.'},deployment:{field:'deployment',entities:['checkout'],note:'One deployment value → one deployment entity.'}};document.querySelectorAll('[data-identity]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-identity]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});const choice=examples[button.dataset.identity];document.getElementById('identity-field').textContent=choice.field;document.getElementById('identity-note').textContent=choice.note;const results=document.getElementById('identity-results');results.replaceChildren(...choice.entities.map(value=>{const chip=document.createElement('span');chip.textContent=value;return chip}))}));})();
